def walk_risk(mails):
    """(0..1, {signal: points}) over the whole thread, oldest mail first."""
    if not mails:
        return 0.0, {}
    last, prev = mails[-1], mails[:-1]
    if last.status == "walked_away":
        return 1.0, {"walked_away": 1.0}
    sig = {}
    if last.status == "final_offer":
        sig["final_offer"] = WALK_WEIGHTS["final_offer"]
    if (n := unchanged(mails)) >= 2:
        sig["price_unchanged_2_rounds"] = WALK_WEIGHTS["price_unchanged_2_rounds"]
    elif n == 1:
        sig["price_unchanged_1_round"] = WALK_WEIGHTS["price_unchanged_1_round"]
    delays = [m.delay for m in prev if m.delay is not None]
    if last.delay is not None and delays and last.delay > min(delays):
        sig["reply_delay_rising"] = WALK_WEIGHTS["reply_delay_rising"]
        if allowed:
            near = isinstance(current, int | float) and all(isinstance(o, int | float) for o in allowed)
            out[m["field"]] = min(allowed, key=lambda o: abs(o - current)) if near else allowed[0]
    return out


def weighted_sentence(intel):
    """The cost-share arithmetic by the supplier's own figures, or None."""
    shared = [d for d in intel.cost_drivers if d.get("share_pct") is not None]
    if not shared or intel.cost_impact_pct is None or intel.asked_pct is None or (intel.cost_gap_pct or 0) <= 1.0:
        return None
    items = ", ".join(
        f"{d['series'] or d['name']} {d['change_pct']:+.1f}% at {d['share_pct']:g}% of your cost" for d in shared
    )
    return (
        f"By the figures you gave us - {items} - the weighted effect on the price is about "
        f"{intel.cost_impact_pct:+.1f}%, not the {intel.asked_pct:g}% you ask for."
    )


