        """Sentences code writes in full: the cost-share arithmetic and our payment-term position."""
        st, sid = move["st"], move["st"]["sid"]
        said = self.said.setdefault(sid, set())
        first = not any(m.get("from") == "buyer" for m in st["events"])
        analysis, position = [], []
